  const parseBlocks = (text) => {
    const blocks = [];
    let currentBlock = '';
    let inCode = false;
    
    // Сначала обработаем блоки кода с ```
    const lines = text.split('\n');
    
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      
      // Проверяем на одинарные бэктики в строке
      if (line.trim().match(/^`[^`]+`$/)) {
        // Если это строка с одинарными бэктиками, обрабатываем её как блок кода
        if (currentBlock) {
          blocks.push({ type: 'text', content: currentBlock.trim() });
          currentBlock = '';
        }
        // Убираем бэктики и добавляем как блок кода
        blocks.push({ type: 'code', content: line.trim().slice(1, -1) });
        continue;
      }
      
      if (line.trim().startsWith('```')) {
        if (!inCode) {
          // Начало блока кода
          if (currentBlock) {
            blocks.push({ type: 'text', content: currentBlock.trim() });
            currentBlock = '';
          }
          inCode = true;
          continue;
        } else {
          // Конец блока кода
          blocks.push({ type: 'code', content: currentBlock.trim() });
          currentBlock = '';
          inCode = false;
          continue;
        }
      }
      
      currentBlock += line + '\n';
    }
    
    // Обработаем последний блок
    if (currentBlock) {
      if (inCode) {
        blocks.push({ type: 'code', content: currentBlock.trim() });
      } else {
        blocks.push({ type: 'text', content: currentBlock.trim() });
      }
    }
    
    return blocks;
  };

